(()=>{const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const products=LAUNCH_PRODUCTS.map(p=>({...p,group:p.category==='คณิตศาสตร์'?'math':p.category==='ระบายสี'?'color':'lang'}));const url=p=>'/books/?product='+encodeURIComponent(p.id);const grid=document.getElementById('product-grid');grid.innerHTML=products.filter(p=>!p.status||p.status==='published').map(p=>`<article class="product" data-group="${p.group}" data-search="${escape(p.name+' '+p.category+' '+p.description)}"><a class="cover" href="${url(p)}" aria-label="ดูรายละเอียด ${escape(p.name)}"><span class="tag">${escape(p.category)}</span>${p.image?`<img src="${escape(p.image)}" alt="ตัวอย่าง ${escape(p.name)}" loading="lazy">`:`<div class="book"><small>PAVNO DIGITAL</small>PAVNO</div>`}</a><div class="copy"><div class="category">${escape(p.category)}</div><h3><a href="${url(p)}">${escape(p.name)}</a></h3><p class="description">${escape(p.description)}</p><div class="product-bottom"><span class="price">${p.price===null?'เร็ว ๆ นี้':'฿'+p.price}<small>${p.price===null?'ยังไม่กำหนดราคา':'ชำระด้วย PromptPay / บัตร'}</small></span><a href="${url(p)}">ดูรายละเอียด ↗</a></div></div></article>`).join('');let group='all';const search=document.getElementById('search');function filter(){const term=search.value.trim().toLocaleLowerCase('th');let n=0;grid.querySelectorAll('.product').forEach(card=>{card.hidden=!((group==='all'||card.dataset.group===group)&&card.dataset.search.toLocaleLowerCase('th').includes(term));if(!card.hidden)n++});document.getElementById('empty').hidden=n>0;document.getElementById('count').textContent=`แสดง ${n} รายการ`}document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{group=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});filter()}));search.addEventListener('input',filter);filter();const menu=document.querySelector('.menu'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));})();
